[{"role": "system", "content": "Propose the actions people can attempt so the listed behaviors can happen. An action is something a person chooses to try (hold a meeting, reopen an issue, attach a condition to support, vote, deploy); things that happen on their own each tick are processes and are not actions. Do not repeat an existing action or propose another that does what one already does. Fields name the entities or values the attempt needs (entity_ref for an entity); the person attempting it is implied, so never add an actor field. Name in for_behaviors the request_ids each action serves. Preserve independent technical condition, report lineage, delivery, personal stance, recorded assent and public hold. Residents choose their responses. No rule may force a stance or assent from evidence, require conflict or agreement, or turn elapsed time into successful repair. The compiled independent procedure owns technical intervention, authorized validation, hold, public positions and assent; do not duplicate or write those components. The compiled send-report delivers statements, questions, requests for evidence and warnings in the actor's own words. Private consideration, interpretation and ignoring are resident-policy choices and memory, not additional rule actions. Additional actions must change an explicitly requested material or institutional record beyond a private done flag. Waiting is permitted."}, {"role": "user", "content": "{
  "people": [
    {
      "id": "ari",
      "position": "Validation engineer"
    },
    {
      "id": "mara",
      "position": "Coordinator"
    },
    {
      "id": "bo",
      "position": "Prototype pump operator"
    }
  ],
  "behaviors_to_cover": [
    {
      "request_id": "request_or_investigate_evidence",
      "behavior": "Each actor may independently request evidence or investigate a claim; doing so does not itself change the pump's technical condition.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "share_or_withhold_evidence",
      "behavior": "Ari may choose whether to communicate a report or private test detail, and whom to tell. A delivered report may be interpreted, ignored, disputed, or retained without changing the pump's actual condition.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "file_validation_hold",
      "behavior": "A validation hold may be filed under the public procedure. Filing publicly reveals failed validation, but does not reveal private test details.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "repair_and_revalidate",
      "behavior": "Ari may perform an explicit technical repair and then authorized revalidation. Repair is an intervention on the pump; review completion and waiting are not repairs. Revalidation may pass or fail. A passing revalidation clears only the technical hold.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "independent_activation_assent",
      "behavior": "Mara and Bo may independently retain support, dissent, request review, or record or withhold their own assent. Neither reports nor rules force persuasion, a change of support, or assent. Activation requires passing validation and each required actor's own recorded assent.",
      "classification": "to_generate",
      "by": null
    },
    {
      "request_id": "false_warning",
      "behavior": "An actor may communicate a warning that is false or disputed. Its delivery and interpretation may affect what people know or believe, but it cannot change the pump's actual technical condition.",
      "classification": "to_generate",
      "by": null
    }
  ],
  "existing_actions": [
    {
      "kind": "communicate",
      "description": "Deliver one represented information item to its declared recipient."
    },
    {
      "kind": "send-report",
      "description": "Send your own words directly to another person; records exposure, not belief or agreement."
    },
    {
